                command("RUNSQL SQL('INSERT INTO QGPL/SQLCHILD VALUES(2)') COMMIT(*NONE)")
                wait_for(lambda: '1 rows affected' in screen.line(24), 'disabled relationship permits an unmatched child')
                command('CHGPFCST FILE(QGPL/SQLCHILD) CST(SQLREF) STATE(*ENABLED)')
                wait_for(lambda: 'CPF32B2' in screen.line(24), 'enabling invalid data commits a check-pending state')
                command("RUNSQL SQL('INSERT INTO QGPL/SQLCHILD VALUES(1)') COMMIT(*NONE)")
                wait_for(lambda: 'SQL0971' in screen.line(24), 'pending relationship rejects child I/O')
                command('CHGPFCST FILE(QGPL/SQLCHILD) CST(*CHKPND) STATE(*DISABLED)')
