                command('CRTLIB LIB(SQLAUTO)')
                wait_for(lambda: 'Library created.' in screen.line(24), 'create destination for a defined relationship')
                command('CRTDUPOBJ OBJ(SQLCHILD) FROMLIB(QGPL) OBJTYPE(*FILE) TOLIB(SQLAUTO)')
