                command("RUNSQL SQL('CREATE TABLE SQLAUTO/SQLPARENT(ID INTEGER PRIMARY KEY)') COMMIT(*NONE)")
                wait_for(lambda: 'SQL statement completed' in screen.line(24), 'creating the parent automatically establishes the relationship')
                command("RUNSQL SQL('INSERT INTO SQLAUTO/SQLCHILD VALUES(2)') COMMIT(*NONE)")
                wait_for(lambda: 'SQL0530' in screen.line(24), 'automatically established relationship enforces child writes')
                command("RUNSQL SQL('INSERT INTO SQLAUTO/SQLPARENT VALUES(1)') COMMIT(*NONE)")
                wait_for(lambda: '1 rows affected' in screen.line(24), 'populate the parent before removing its member')
                command("RUNSQL SQL('INSERT INTO SQLAUTO/SQLCHILD VALUES(1)') COMMIT(*NONE)")
                wait_for(lambda: '1 rows affected' in screen.line(24), 'populate the dependent before member removal')
                command('RMVM SQLAUTO/SQLPARENT SQLP*')
                wait_for(lambda: '1 members removed' in screen.line(24), 'remove a referenced member while preserving the relationship definition')
                command("RUNSQL SQL('INSERT INTO SQLAUTO/SQLCHILD VALUES(2)') COMMIT(*NONE)")
                wait_for(lambda: '1 rows affected' in screen.line(24), 'defined relationship permits dependent writes')
                command('ADDPFM FILE(SQLAUTO/SQLPARENT) MBR(REPLACED)')
                wait_for(lambda: 'Member REPLACED added' in screen.line(24), 'recreate the parent member under a different name')
                command("RUNSQL SQL('INSERT INTO SQLAUTO/SQLCHILD VALUES(3)') COMMIT(*NONE)")
                wait_for(lambda: 'SQL0971' in screen.line(24), 'reestablishment marks unmatched surviving records pending')
                command('CHGPFCST FILE(SQLAUTO/SQLCHILD) CST(*ALL) STATE(*DISABLED)')
                wait_for(lambda: '1 constraints changed' in screen.line(24), 'disable the reestablished relationship for repair')
                command("RUNSQL SQL('INSERT INTO SQLAUTO/SQLPARENT VALUES(1),(2)') COMMIT(*NONE)")
                wait_for(lambda: '2 rows affected' in screen.line(24), 'repair replacement parent data for both surviving child records')
                command('CHGPFCST FILE(SQLAUTO/SQLCHILD) CST(*ALL) STATE(*ENABLED)')
                wait_for(lambda: '1 constraints changed' in screen.line(24), 'verify and enable the repaired relationship')
                command("RUNSQL SQL('INSERT INTO SQLAUTO/SQLCHILD VALUES(3)') COMMIT(*NONE)")
                wait_for(lambda: 'SQL0530' in screen.line(24), 'replacement member enforces the restored relationship')
                command('RMVM FILE(SQLAUTO/SQLPARENT) MBR(*ALL)')
